SELECT A.prod_id prodId, A.SETTDATE_DATE confirmDate, A.FPROD_ID fprodId, SUM(A.SUB_AMT) subAmt, SUM(A.RED_AMT) redAmt, SUM(A.BONUS_AMT) bonusAmt, SUM(A.SUB_TRADE_PRINCE) subTradePrince, SUM(A.RED_TRADE_PRINCE) redTradePrince, SUM(A.RED_INT_AMT) redIntAmt FROM (
SELECT if(cpd.prod_id=NULL,cpd.fprod_id,cpd.prod_id) prod_id, cpd.SETTDATE_DATE, cpd.FPROD_ID, CASE WHEN cpd.trade_type IN ('01','02') THEN cpd.TRADE_QTY ELSE 0 END SUB_AMT, CASE WHEN cpd.trade_type IN ('03','17') THEN cpd.TRADE_QTY ELSE 0 END RED_AMT, CASE WHEN cpd.trade_type IN ('05') THEN cpd.TRADE_QTY ELSE 0 END BONUS_AMT, CASE WHEN cpd.trade_type IN ('01','02') THEN if(cpd.status='D',-1,1)*cpd.TRADE_PRINCE ELSE 0 END SUB_TRADE_PRINCE, CASE WHEN cpd.trade_type IN ('03','17') THEN if(cpd.status='D',-1,1)*cpd.TRADE_PRINCE ELSE 0 END RED_TRADE_PRINCE, CASE WHEN cpd.trade_type IN ('03','17') THEN if(cpd.status='D',-1,1)*cpd.INT_AMT ELSE 0 END RED_INT_AMT FROM CHB_PRD_DEAL cpd WHERE 1=1 AND cpd.trade_type IN ('01','02','03','05','17') AND DATE_FORMAT(cpd.update_time,'%Y-%m-%d') = #{executeDateStr,jdbcType=VARCHAR} AND DATE_FORMAT(cpd.SETTDATE_DATE,'%Y-%m-%d') = #{executeDateStr,jdbcType=VARCHAR} AND cpd.status = 'E'
UNION ALL SELECT if(prod_id=NULL,fprod_id,prod_id) prod_id, L.SETTDATE_DATE, L.FPROD_ID, CASE WHEN L.trade_type IN ('01','02') THEN if(L.status='D',-1,1)*L.TRADE_QTY ELSE 0 END SUB_AMT, CASE WHEN L.trade_type IN ('03','17') THEN if(L.status='D',-1,1)*L.TRADE_QTY ELSE 0 END RED_AMT, CASE WHEN L.trade_type IN ('05') THEN if(L.status='D',-1,1)*L.TRADE_QTY ELSE 0 END BONUS_AMT, CASE WHEN L.trade_type IN ('01','02') THEN if(L.status='D',-1,1)*L.TRADE_PRINCE ELSE 0 END SUB_TRADE_PRINCE, CASE WHEN L.trade_type IN ('03','17') THEN if(L.status='D',-1,1)*L.TRADE_PRINCE ELSE 0 END RED_TRADE_PRINCE, CASE WHEN L.trade_type IN ('03','17') THEN if(L.status='D',-1,1)*L.INT_AMT ELSE 0 END RED_INT_AMT FROM CHB_PRD_DEAL L WHERE 1=1 AND L.trade_type IN ('01','02','03','05','17')
AND EXISTS ( SELECT 1 FROM CHB_PRD_DEAL S WHERE DATE_FORMAT(S.update_time,'%Y-%m-%d') = #{executeDateStr,jdbcType=VARCHAR} AND DATE_FORMAT(S.SETTDATE_DATE,'%Y-%m-%d') != #{executeDateStr,jdbcType=VARCHAR} AND DATE_FORMAT(S.CREATE_TIME,'%Y-%m-%d') != #{executeDateStr,jdbcType=VARCHAR}
AND S.PROD_ID=L.PROD_ID AND DATE_FORMAT(S.SETTDATE_DATE,'%Y-%m-%d') = DATE_FORMAT(L.SETTDATE_DATE,'%Y-%m-%d') )
)A GROUP BY A.prod_id, A.SETTDATE_DATE, A.FPROD_ID

mapper.update:
UPDATE REP_PRODTRD as A, ( select SEQ_NO, PROD_ID, CONFIRM_DATE, SUB_AMT, RED_AMT, BONUS_AMT, CAPITAL, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME, INPUT_TYPE, INPUT_USER, ADAPTER_ID, FPROD_ID, SUB_TRADE_PRINCE, RED_TRADE_PRINCE, RED_INT_AMT from ( select TEMP.* from (
select #{item.seqNo,jdbcType=VARCHAR} SEQ_NO, #{item.prodId,jdbcType=VARCHAR} PROD_ID, #{item.confirmDate,jdbcType=DATE} CONFIRM_DATE, #{item.subAmt,jdbcType=DECIMAL} SUB_AMT, #{item.redAmt,jdbcType=DECIMAL} RED_AMT, #{item.bonusAmt,jdbcType=DECIMAL} BONUS_AMT, #{item.capital,jdbcType=DECIMAL} CAPITAL, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, #{item.createDept,jdbcType=VARCHAR} CREATE_DEPT, #{item.createTime,jdbcType=TIMESTAMP} CREATE_TIME, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, #{item.updateTime,jdbcType=TIMESTAMP} UPDATE_TIME, #{item.inputType,jdbcType=VARCHAR} INPUT_TYPE, #{item.inputUser,jdbcType=VARCHAR} INPUT_USER, #{item.adapterId,jdbcType=VARCHAR} ADAPTER_ID, #{item.fprodId,jdbcType=VARCHAR} FPROD_ID, #{item.subTradePrince,jdbcType=DECIMAL} SUB_TRADE_PRINCE, #{item.redTradePrince,jdbcType=DECIMAL} RED_TRADE_PRINCE, #{item.redIntAmt,jdbcType=DECIMAL} RED_INT_AMT from dual
) TEMP ) de ) AS B SET
A.SUB_AMT = B.SUB_AMT + A.SUB_AMT, A.RED_AMT = B.RED_AMT + A.RED_AMT, A.BONUS_AMT = B.BONUS_AMT + A.BONUS_AMT, A.CAPITAL = B.CAPITAL + A.CAPITAL, A.CREATE_USER = B.CREATE_USER, A.CREATE_DEPT = B.CREATE_DEPT, A.CREATE_TIME = B.CREATE_TIME, A.UPDATE_USER = B.UPDATE_USER, A.UPDATE_TIME = B.UPDATE_TIME, A.INPUT_TYPE = B.INPUT_TYPE, A.INPUT_USER = B.INPUT_USER, A.ADAPTER_ID = B.ADAPTER_ID, A.SUB_TRADE_PRINCE = B.SUB_TRADE_PRINCE + A.SUB_TRADE_PRINCE, A.RED_TRADE_PRINCE = B.RED_TRADE_PRINCE + A.RED_TRADE_PRINCE, A.RED_INT_AMT = B.RED_INT_AMT + A.RED_INT_AMT where A.PROD_ID = B.PROD_ID AND A.CONFIRM_DATE = B.CONFIRM_DATE; insert into REP_PRODTRD ( SEQ_NO, PROD_ID, CONFIRM_DATE, SUB_AMT, RED_AMT, BONUS_AMT, CAPITAL, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME, INPUT_TYPE, INPUT_USER, ADAPTER_ID, FPROD_ID, SUB_TRADE_PRINCE, RED_TRADE_PRINCE, RED_INT_AMT ) select SEQ_NO, PROD_ID, CONFIRM_DATE, SUB_AMT, RED_AMT, BONUS_AMT, CAPITAL, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME, INPUT_TYPE, INPUT_USER, ADAPTER_ID, FPROD_ID, SUB_TRADE_PRINCE, RED_TRADE_PRINCE, RED_INT_AMT from ( select TEMP.* from (
select #{item.seqNo,jdbcType=VARCHAR} SEQ_NO, #{item.prodId,jdbcType=VARCHAR} PROD_ID, #{item.confirmDate,jdbcType=DATE} CONFIRM_DATE, #{item.subAmt,jdbcType=DECIMAL} SUB_AMT, #{item.redAmt,jdbcType=DECIMAL} RED_AMT, #{item.bonusAmt,jdbcType=DECIMAL} BONUS_AMT, #{item.capital,jdbcType=DECIMAL} CAPITAL, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, #{item.createDept,jdbcType=VARCHAR} CREATE_DEPT, #{item.createTime,jdbcType=TIMESTAMP} CREATE_TIME, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, #{item.updateTime,jdbcType=TIMESTAMP} UPDATE_TIME, #{item.inputType,jdbcType=VARCHAR} INPUT_TYPE, #{item.inputUser,jdbcType=VARCHAR} INPUT_USER, #{item.adapterId,jdbcType=VARCHAR} ADAPTER_ID, #{item.fprodId,jdbcType=VARCHAR} FPROD_ID, #{item.subTradePrince,jdbcType=DECIMAL} SUB_TRADE_PRINCE, #{item.redTradePrince,jdbcType=DECIMAL} RED_TRADE_PRINCE, #{item.redIntAmt,jdbcType=DECIMAL} RED_INT_AMT from dual
) TEMP where not exists (select 1 from REP_PRODTRD CII where CII.PROD_ID = TEMP.PROD_ID AND CII.CONFIRM_DATE = TEMP.CONFIRM_DATE) ) de
